import _sodium from 'libsodium-wrappers';

// Base64 encoded file contents to avoid JS parser string termination issues
const WORKFLOW_YAML_B64 = "";
const SCRIPT_JS_B64 = "";

const WORKFLOW_YAML = atob(WORKFLOW_YAML_B64);
const SCRIPT_JS = atob(SCRIPT_JS_B64);

const ISSUE_WORKFLOW_YAML_B64 = "";
const ISSUE_SCRIPT_JS_B64 = "";

const ISSUE_WORKFLOW_YAML = atob(ISSUE_WORKFLOW_YAML_B64);
const ISSUE_SCRIPT_JS = atob(ISSUE_SCRIPT_JS_B64);

export const INSTALLER_VERSION = 3;


/**
 * Encrypt a secret using the repository's public key
 */
async function encryptSecret(secret, publicKeyBase64) {
  await _sodium.ready;
  const sodium = _sodium;
  const binkey = sodium.from_base64(publicKeyBase64, sodium.base64_variants.ORIGINAL);
  const binsec = sodium.from_string(secret);
  const encBytes = sodium.crypto_box_seal(binsec, binkey);
  return sodium.to_base64(encBytes, sodium.base64_variants.ORIGINAL);
}

/**
 * Authenticate via GitHub and return the token
 * We use the provided PAT for simplicity as an MVP before requiring an OAuth App Client ID.
 */
async function getGitHubToken(providedPat) {
  if (providedPat) return providedPat;
  throw new Error("No GitHub Personal Access Token provided. Please enter one.");
}

/**
 * 1. Pushes a file to the GitHub repository using the Contents API
 */
async function pushFile(token, owner, repo, path, contentStr, commitMessage) {
  const contentBase64 = btoa(unescape(encodeURIComponent(contentStr)));
  const apiUrl = `https://api.github.com/repos/${owner}/${repo}/contents/${path}`;

  // Check if file exists to get the SHA (required for updating)
  let sha;
  try {
    const res = await fetch(apiUrl, { headers: { 'Authorization': `Bearer ${token}` } });
    if (res.ok) {
      const data = await res.json();
      sha = data.sha;
    }
  } catch (e) {
    // File doesn't exist, ignore
  }

  const payload = {
    message: commitMessage,
    content: contentBase64,
  };
  if (sha) payload.sha = sha;

  const pushRes = await fetch(apiUrl, {
    method: 'PUT',
    headers: {
      'Authorization': `Bearer ${token}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(payload)
  });

  if (!pushRes.ok) {
    const err = await pushRes.json();
    throw new Error(`Failed to push ${path}: ${err.message}`);
  }
}

/**
 * 2. Uploads a named secret to the repository
 */
async function pushSecret(token, owner, repo, secretName, secretValue, cachedKeyData = null) {
  let publicKeyId, publicKey;

  if (cachedKeyData) {
    publicKeyId = cachedKeyData.key_id;
    publicKey = cachedKeyData.key;
  } else {
    // Step A: Fetch the public key
    const keyRes = await fetch(`https://api.github.com/repos/${owner}/${repo}/actions/secrets/public-key`, {
      headers: { 'Authorization': `Bearer ${token}` }
    });
    if (!keyRes.ok) {
      const err = await keyRes.json();
      throw new Error(`Failed to fetch public key: ${err.message}`);
    }
    const keyData = await keyRes.json();
    publicKeyId = keyData.key_id;
    publicKey = keyData.key;
  }

  // Step B: Encrypt the secret
  const encryptedValue = await encryptSecret(secretValue, publicKey);

  // Step C: Upload the secret
  const putRes = await fetch(`https://api.github.com/repos/${owner}/${repo}/actions/secrets/${secretName}`, {
    method: 'PUT',
    headers: {
      'Authorization': `Bearer ${token}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      encrypted_value: encryptedValue,
      key_id: publicKeyId
    })
  });

  if (!putRes.ok) {
    const err = await putRes.json();
    throw new Error(`Failed to upload secret ${secretName}: ${err.message}`);
  }

  return { key_id: publicKeyId, key: publicKey };
}

/**
 * Main initialization flow
 */
export async function initializeRepoOwl(repoFullName, githubPat, groqApiKey, broadcast, supabaseUrl, supabaseAnonKey) {
  const [owner, repo] = repoFullName.split('/');
  
  if (!groqApiKey) {
    throw new Error("GROQ_API_KEY is not set in extension options.");
  }
  
  const token = await getGitHubToken(githubPat);

  // 1. Push PR Analyzer Workflow
  broadcast?.('Pushing PR analyzer workflow...');
  await pushFile(token, owner, repo, '.github/workflows/repoowl-analyze.yml', WORKFLOW_YAML, 'Initialize RepoOwl PR Analyzer Action');
  
  // 2. Push PR Analyzer Script
  broadcast?.('Pushing PR analyzer script...');
  await pushFile(token, owner, repo, '.github/scripts/analyze-pr.js', SCRIPT_JS, 'Add RepoOwl Map-Reduce script');

  // 3. Push Issue Analyzer Workflow
  broadcast?.('Pushing Issue analyzer workflow...');
  await pushFile(token, owner, repo, '.github/workflows/issue-analyze.yml', ISSUE_WORKFLOW_YAML, 'Initialize RepoOwl Issue Analyzer Action');

  // 4. Push Issue Analyzer Script
  broadcast?.('Pushing Issue analyzer script...');
  await pushFile(token, owner, repo, '.github/scripts/analyze-issue.js', ISSUE_SCRIPT_JS, 'Add RepoOwl Issue Analyzer script');

  // 5. Push GROQ_API_KEY secret (and cache the public key for reuse)
  broadcast?.('Uploading GROQ_API_KEY secret...');
  let keyData = await pushSecret(token, owner, repo, 'GROQ_API_KEY', groqApiKey);

  // 6. Push Supabase secrets (reuse the cached public key to avoid an extra API call)
  if (supabaseUrl) {
    broadcast?.('Uploading SUPABASE_URL secret...');
    await pushSecret(token, owner, repo, 'SUPABASE_URL', supabaseUrl, keyData);
  }
  if (supabaseAnonKey) {
    broadcast?.('Uploading SUPABASE_ANON_KEY secret...');
    await pushSecret(token, owner, repo, 'SUPABASE_ANON_KEY', supabaseAnonKey, keyData);
  }

  return true;
}
